'use strict';
const root = document.querySelector('#demo');
const feature = new URLSearchParams(location.search).get('feature') || 'games';
const allowed = ['games','reps','calories','progress','metrics'];
const cleanup = [];
const $ = selector => root.querySelector(selector);
const escapeHTML = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const previewHeading = title => `<div class="top"><span>footprint</span><span>Interactive preview</span></div><h1>${title}</h1>`;
const emit = () => parent.postMessage({type:'footprint-demo-interaction'},location.origin);
root.addEventListener('pointerdown', emit, {passive:true});
root.addEventListener('keydown', emit);
function listen(selector,event,handler){$(selector)?.addEventListener(event,handler);}
function stopTimers(){cleanup.forEach(stop=>stop());}
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopTimers();});
window.addEventListener('message',event=>{if(event.source===parent&&event.data?.type==='footprint-demo-visibility'&&!event.data.active)stopTimers();});
fetch('../assets/app-preview/source-art.json').then(response=>{if(!response.ok)throw Error('Preview unavailable');return response.json();}).then(art=>{
  if(!allowed.includes(feature))throw Error('Unknown preview');
  ({games:()=>games(art),reps:battle,calories:()=>pet(art),progress:()=>ranks(art),metrics:photos})[feature]();
}).catch(()=>{root.innerHTML='<div class="loading">This preview could not load. Please refresh the page.</div>';});

function games(art){
 let country=art.countries.find(c=>c.name==='Japan')||art.countries[0],fraction=.23,mode='country',score=0,hits=0,active=false,ready=false,targetTimer,missTimer;
 function stopBoxing(){active=false;ready=false;clearTimeout(targetTimer);clearTimeout(missTimer);if($('#boxing-start'))$('#boxing-start').textContent='Start round';}
 cleanup.push(stopBoxing);
 function mapProgress(){
  const paths=[];let remaining=country.totalKm*fraction,marker=country.rings[0].points[0],stopped=false;
  for(const ring of country.rings){if(stopped)break;let path=`M ${ring.points[0].join(' ')}`;for(let i=0;i<ring.lengths.length;i++){const a=ring.points[i],b=ring.points[i+1],distance=ring.lengths[i],f=distance>0?Math.min(1,remaining/distance):1;marker=[a[0]+(b[0]-a[0])*f,a[1]+(b[1]-a[1])*f];path+=` L ${marker.join(' ')}`;remaining=Math.max(0,remaining-distance);if(f<1||remaining<=.00001){stopped=true;break;}}paths.push(path);}
  const all=country.rings.flatMap(r=>r.points),xs=all.map(p=>p[0]),ys=all.map(p=>p[1]),x=Math.min(...xs)-48,y=Math.min(...ys)-48,w=Math.max(...xs)-x+48,h=Math.max(...ys)-y+48;
  $('.map-stage').innerHTML=`<svg viewBox="${x} ${y} ${w} ${h}" role="img" aria-label="${country.name} border route, ${Math.round(fraction*100)} percent complete"><path d="${country.rings.map(r=>'M '+r.points.map(p=>p.join(' ')).join(' L ')+' Z').join(' ')}" fill="#a3e63512" stroke="#60666d" stroke-width="4" stroke-linejoin="round"/>${paths.map(d=>`<path d="${d}" fill="none" stroke="#a3e635" stroke-width="12" stroke-linecap="round" stroke-linejoin="round"/>`).join('')}<circle cx="${marker[0]}" cy="${marker[1]}" r="20" fill="#a3e63533"/><circle cx="${marker[0]}" cy="${marker[1]}" r="10" fill="#a3e635" stroke="#141417" stroke-width="4"/></svg>`;
  $('#team-distance').textContent=Math.round(country.totalKm*fraction).toLocaleString();$('#route-percent').textContent=Math.round(fraction*100)+'% complete';$('#route-fill').style.width=fraction*100+'%';
 }
 function target(){if(!active)return;ready=false;const left=hits%2===0;$('.mitt').innerHTML=art.mitts[left?'l':'r'];$('.mitt').style.left=(left?'10%':'53%');$('.mitt').style.top=(38+(hits%3)*8)+'px';$('.boxing-status').textContent='GET READY';targetTimer=setTimeout(()=>{if(!active)return;ready=true;$('.boxing-status').textContent='HIT NOW · TAP THE PAD';missTimer=setTimeout(()=>{if(!active)return;$('.boxing-status').textContent='MISSED · NEXT PAD';ready=false;targetTimer=setTimeout(target,450);},1900);},500);}
 function render(){
  root.innerHTML=previewHeading('Play. Move. Together.')+`<div class="tabs" aria-label="Game preview"><button data-game="country" class="${mode==='country'?'selected':''}">Country quests</button><button data-game="boxing" class="${mode==='boxing'?'selected':''}">Boxing</button></div>`+(mode==='country'?`<div class="panel"><div class="eyebrow">WALK THE WORLD TOGETHER</div><h2 style="margin-top:8px">Your squad. One shared route.</h2><label class="muted" for="country">Choose a country</label><select class="select" id="country">${art.countries.map(c=>`<option value="${c.id}" ${c.id===country.id?'selected':''}>${c.name}</option>`).join('')}</select><div class="map-stage"></div><div class="row"><div><span class="value" id="team-distance"></span><span class="muted"> km</span><p class="muted">walked together</p></div><span class="pill" id="route-percent"></span></div><div class="track"><div class="fill" id="route-fill"></div></div><div class="avatar-row"><i>Y</i><i>A</i><i>S</i> Your sample squad</div><button class="primary full" id="team-step">Try a team day +</button><p class="note">Demo progress. The app combines your squad's recorded walks.</p></div><button class="reset" id="route-reset">Reset route</button>`:`<div class="panel"><div class="row"><span class="eyebrow">SHADOWBOXING</span><span class="pill">Tap-to-play demo</span></div><div class="row" style="margin-top:13px"><div><span class="value" id="boxing-score">${score}</span><p class="muted">score</p></div><div><span class="value" id="boxing-hits">${hits}</span><p class="muted">hits</p></div></div><div class="boxing-stage"><button class="mitt" aria-label="Hit the boxing pad">${art.mitts.l}</button><div class="boxing-status" aria-live="polite">START A ROUND</div></div><button class="primary full" id="boxing-start">Start round</button><p class="note">Tap the pad when it says HIT NOW. The app uses your camera to track punches.</p></div>`);
  root.querySelectorAll('[data-game]').forEach(button=>button.onclick=()=>{stopBoxing();mode=button.dataset.game;render();});
  if(mode==='country'){mapProgress();listen('#country','change',event=>{country=art.countries.find(c=>c.id===event.target.value);fraction=.23;mapProgress();});listen('#team-step','click',()=>{fraction=Math.min(1,fraction+.1);mapProgress();$('#team-step').textContent=fraction===1?'Route complete ✓':'Try a team day +';});listen('#route-reset','click',()=>{fraction=0;mapProgress();$('#team-step').textContent='Try a team day +';});}
  else{listen('#boxing-start','click',()=>{if(active){stopBoxing();$('.boxing-status').textContent='ROUND PAUSED';}else{active=true;$('#boxing-start').textContent='Pause round';target();}});listen('.mitt','click',()=>{if(!active||!ready)return;clearTimeout(missTimer);ready=false;hits++;score+=10+Math.min(20,hits*2);$('#boxing-score').textContent=score;$('#boxing-hits').textContent=hits;$('.boxing-status').textContent='NICE HIT!';targetTimer=setTimeout(target,250);});}
 }
 render();
}

function battle(){
 let own=8,friend=6,rivalTimer,punchTimer;
 root.innerHTML=previewHeading('Push-up battle')+`<span class="pill">Sample head-to-head session</span><div class="panel"><div class="scoreboard"><div class="score-box you"><span>YOU</span><strong id="own-reps" class="green">8</strong><span>REPS</span></div><div class="score-box"><span>FRIEND</span><strong id="friend-reps">6</strong><span>REPS</span></div></div><div class="battle-bar" role="progressbar" aria-label="Your share of the battle" aria-valuemin="0" aria-valuemax="100" aria-valuenow="60"><div class="fill" style="width:60%"></div></div><p class="muted">Lead by 10 reps to fill the bar and win.</p><div class="pose-stage"><svg viewBox="0 0 240 170" aria-label="Illustrative push-up pose"><path d="M20 140H220" stroke="#a3e63533" stroke-width="2"/><g class="person" fill="none" stroke="#a3e635" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"><path d="M58 82 120 97 181 128M65 86 85 113 74 139M121 97 165 114 198 138"/><circle cx="43" cy="71" r="15"/><g fill="#e9f8ce" stroke-width="2"><circle cx="58" cy="82" r="4"/><circle cx="120" cy="97" r="4"/><circle cx="85" cy="113" r="4"/></g></g></svg></div><button class="primary full" id="rep-add">Count a push-up +</button><div class="actions"><button class="secondary" id="friend-add">Friend +1</button><button class="secondary" id="rival-auto" aria-pressed="false">Auto rival: off</button></div><div class="feedback" id="battle-feedback" role="status">You're 2 reps ahead. Keep going!</div></div><button class="reset" id="battle-reset">Reset battle</button><p class="note">Interactive sample. Real app battles use camera-counted reps; this preview uses taps.</p>`;
 function stop(){clearInterval(rivalTimer);rivalTimer=undefined;$('#rival-auto').textContent='Auto rival: off';$('#rival-auto').setAttribute('aria-pressed','false');}cleanup.push(stop);
 function update(){const lead=own-friend,share=Math.max(0,Math.min(100,50+lead*5));$('#own-reps').textContent=own;$('#friend-reps').textContent=friend;$('.fill').style.width=share+'%';$('.battle-bar').setAttribute('aria-valuenow',share);const won=Math.abs(lead)>=10;$('#battle-feedback').textContent=won?(lead>0?'You win! A 10-rep lead. Start another round?':'Your friend wins this round. Try again!'):(lead===0?'All tied up. Your next rep matters!':lead>0?`You're ${lead} reps ahead. Keep going!`:`Your friend is ${-lead} reps ahead. Catch up!`);$('#rep-add').disabled=won;$('#friend-add').disabled=won;if(won)stop();}
 listen('#rep-add','click',()=>{own++;$('.pose-stage').classList.add('down');clearTimeout(punchTimer);punchTimer=setTimeout(()=>$('.pose-stage').classList.remove('down'),200);update();});listen('#friend-add','click',()=>{friend++;update();});listen('#rival-auto','click',()=>{if(rivalTimer)stop();else if(Math.abs(own-friend)<10){$('#rival-auto').textContent='Auto rival: on';$('#rival-auto').setAttribute('aria-pressed','true');rivalTimer=setInterval(()=>{friend++;update();},1600);}});listen('#battle-reset','click',()=>{stop();own=8;friend=6;update();});
}

function pet(art){
 let calories=1220,petted=false,resetPetTimer,target=2450;
 root.innerHTML=previewHeading('Your daily companion')+`<div class="row"><div><div class="eyebrow">GROW TOGETHER</div><h2 style="margin-top:6px">Pip</h2></div><span class="pill">Lv. 1</span></div><div class="panel"><div class="row"><span class="pill" id="pet-mood">Getting fueled</span><span class="muted">Maintain plan</span></div><div class="feedback" id="pet-dialogue" role="status">Mmm, getting fueled! We're finding our rhythm.</div><div class="pet-stage" aria-label="Pip the nutrition pet"><div class="pet-scale"></div><button class="pet-head" aria-label="Rub Pip's head"></button></div><p class="muted" style="text-align:center">Rub my head, or tap to say hello.</p><div class="stats"><div><span class="small-value" id="pet-calories">1,220 kcal</span><span class="muted">logged today</span></div><div><span class="small-value">2,450 kcal</span><span class="muted">maintain target</span></div></div><div class="track"><div class="fill" id="pet-fill" style="width:50%"></div></div><p class="muted" id="pet-percent">50% of today's target</p><button class="primary full" id="pet-feed">Log a sample meal +</button></div><button class="reset" id="pet-reset">Reset diary</button><p class="note">Sample diary only. In the app, logging real meals feeds Pip; care levels grow with logging days.</p>`;
 function update(){let mood=calories/target>=.85?'satisfied':'energized';$('.pet-scale').innerHTML=art.pets[petted?'satisfied':mood];$('#pet-calories').textContent=calories.toLocaleString()+' kcal';$('#pet-fill').style.width=Math.min(100,calories/target*100)+'%';$('#pet-percent').textContent=Math.round(calories/target*100)+"% of today's target";$('#pet-mood').textContent=calories>=target*.85?'Satisfied':'Getting fueled';$('#pet-dialogue').textContent=petted?'Purrr... those head rubs are the best!':calories>=target*.85?"Happy belly! We're right around today's target.":"Mmm, getting fueled! We're finding our rhythm.";$('#pet-feed').disabled=calories>=target;$('#pet-feed').textContent=calories>=target?'Diary ready for today ✓':'Log a sample meal +';}
 function rub(){petted=true;update();$('.pet-stage').classList.remove('is-petted');void $('.pet-stage').offsetWidth;$('.pet-stage').classList.add('is-petted');clearTimeout(resetPetTimer);resetPetTimer=setTimeout(()=>{petted=false;update();},3000);}
 let lastX=null,lastRub=0;listen('.pet-head','pointermove',event=>{if(lastX!==null&&Math.abs(event.clientX-lastX)>8&&Date.now()-lastRub>750){rub();lastRub=Date.now();}lastX=event.clientX;});listen('.pet-head','click',rub);listen('#pet-feed','click',()=>{calories=Math.min(target,calories+350);update();});listen('#pet-reset','click',()=>{calories=1220;petted=false;clearTimeout(resetPetTimer);update();});update();
}

function ranks(art){
 let tab='ranks',part='arms',tier=2;const parts=['arms','chest','shoulders','back','core','legs'];
 const badges=[['Pathfinder','◈','Accumulate lifetime steps.'],['Trek Master','⌁','Complete recorded outdoor walks.'],['Horizon Seeker','◎','Build your total walking distance.'],['Streak Titan','♨','Keep your daily walking streak.'],['Apex Strider','✧','Reach a new daily step record.'],['Endurance Pioneer','◷','Keep moving on longer walks.']];
 function render(){const t=art.tiers[tier];root.innerHTML=previewHeading('Every effort. A new level.')+`<div class="tabs"><button class="${tab==='ranks'?'selected':''}" data-rank-tab="ranks">Gym ranks</button><button class="${tab==='badges'?'selected':''}" data-rank-tab="badges">Badges</button></div>`+(tab==='ranks'?`<p class="muted">Build your ranks with every pound lifted.</p><div class="rank-stage">${art.bodies[part]}<div class="rank-chip">${art.ranks[t.id]}<span>${part.toUpperCase()}<br><strong style="color:${t.light}">${t.name}</strong></span></div></div><div class="parts">${parts.map(p=>`<button data-part="${p}" class="${p===part?'selected':''}">${p[0].toUpperCase()+p.slice(1)}</button>`).join('')}</div><div class="panel rank-info"><div>${art.ranks[t.id]}</div><div><div class="eyebrow">EXPLORE THE RANK LADDER</div><h2 style="color:${t.light}">${t.name}</h2><span class="muted">${t.volumeLbs.toLocaleString()} lbs threshold</span></div></div><div class="actions"><button class="secondary" id="rank-prev" ${tier===0?'disabled':''}>← Previous</button><button class="primary" id="rank-next" ${tier===art.tiers.length-1?'disabled':''}>Next rank →</button></div><p class="note">Preview the app's actual rank ladder. Body colors show an illustrative workout history.</p>`:`<div class="row"><span class="pill">Consistency earns recognition</span></div><div class="badge-grid">${badges.map(([title,icon],i)=>`<button class="badge" data-badge="${i}"><span class="medal">${icon}</span><strong>${title}</strong></button>`).join('')}</div><div class="feedback" id="badge-detail" role="status">Tap a badge to see what it celebrates.</div><p class="note">A sample badge collection. The app awards tiers from your recorded activity.</p>`);root.querySelectorAll('[data-rank-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.rankTab;render();});root.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>{part=b.dataset.part;render();});listen('#rank-next','click',()=>{tier=Math.min(art.tiers.length-1,tier+1);render();});listen('#rank-prev','click',()=>{tier=Math.max(0,tier-1);render();});root.querySelectorAll('[data-badge]').forEach(b=>b.onclick=()=>{root.querySelectorAll('.badge').forEach(x=>x.classList.remove('active'));b.classList.add('active');const [title,,description]=badges[Number(b.dataset.badge)];$('#badge-detail').textContent=title+' — '+description;});}
 render();
}

function photos(){
 root.innerHTML=previewHeading('See your progress, side by side.')+`<span class="pill">A/B comparison</span><div class="comparison" aria-label="Interactive photo comparison"><img class="photo-after" src="../assets/app-preview/photo-b.jpg" alt="Sample check-in B"><img class="photo-before" src="../assets/app-preview/photo-a.jpg" alt="Sample check-in A"><span class="photo-tag a">A · Earlier check-in</span><span class="photo-tag b">B · Later check-in</span><div class="divider"></div></div><label class="muted" for="comparison-slider">Drag to compare</label><input class="compare-range" id="comparison-slider" aria-label="Photo comparison split" type="range" min="0" max="100" value="50"><div class="actions"><label class="upload">Choose photo A<input type="file" id="photo-a" accept="image/*"></label><label class="upload">Choose photo B<input type="file" id="photo-b" accept="image/*"></label></div><p class="photo-help" id="photo-status" role="status">You can try your own photos. They stay in this browser preview and are never uploaded.</p><button class="reset" id="photo-reset">Reset comparison</button><p class="note">Sample images from the app's demo gallery; not a before-and-after result.</p>`;
 const urls={};function split(value){const amount=Math.max(0,Math.min(100,Number(value)));$('.comparison').style.setProperty('--split',amount+'%');$('#comparison-slider').value=amount;}
 listen('#comparison-slider','input',event=>split(event.target.value));let dragging=false;const drag=event=>{if(!dragging)return;const r=$('.comparison').getBoundingClientRect();split((event.clientX-r.left)/r.width*100);};listen('.comparison','pointerdown',event=>{dragging=true;$('.comparison').setPointerCapture(event.pointerId);drag(event);});listen('.comparison','pointermove',drag);listen('.comparison','pointerup',()=>{dragging=false;});listen('.comparison','pointercancel',()=>{dragging=false;});
 for(const key of ['a','b'])listen('#photo-'+key,'change',event=>{const file=event.target.files[0];if(!file)return;if(!file.type.startsWith('image/')||file.size>10*1024*1024){$('#photo-status').textContent='Choose an image smaller than 10 MB.';return;}if(urls[key])URL.revokeObjectURL(urls[key]);urls[key]=URL.createObjectURL(file);$(key==='a'?'.photo-before':'.photo-after').src=urls[key];$('#photo-status').textContent='Your photo is shown locally. Nothing was uploaded.';});
 listen('#photo-reset','click',()=>{for(const key of ['a','b']){if(urls[key])URL.revokeObjectURL(urls[key]);$(key==='a'?'.photo-before':'.photo-after').src='../assets/app-preview/photo-'+key+'.jpg';$('#photo-'+key).value='';}split(50);$('#photo-status').textContent='Sample comparison restored.';});
}
